 	@Override
 	public Fetch resolveCircularFetch(
 			NavigablePath fetchablePath,
 			FetchParent fetchParent,
 			FetchTiming fetchTiming,
 			DomainResultCreationState creationState) {
 		final var associationKey = foreignKeyDescriptor.getAssociationKey();
 		final boolean associationKeyVisited = creationState.isAssociationKeyVisited( associationKey );
 		if ( associationKeyVisited || bidirectionalAttributePath != null ) {
 			if ( !associationKeyVisited && creationState.isRegisteringVisitedAssociationKeys() ) {
 				// If the current association key hasn't been visited yet and we are registering keys,
 				// then there can't be a circular fetch
 				return null;
 			}
 			final var fetchParentNavigablePath = fetchParent.getNavigablePath();
 			var parentNavigablePath = castNonNull( fetchablePath.getParent() );
 			assert parentNavigablePath.equals( fetchParentNavigablePath )
 				|| fetchParentNavigablePath instanceof TreatedNavigablePath
 						&& parentNavigablePath.equals( fetchParentNavigablePath.getRealParent() );
 			if ( fetchParentNavigablePath instanceof TreatedNavigablePath
 					&& parentNavigablePath.equals( fetchParentNavigablePath.getRealParent() ) ) {
 				// Children of treated paths report the untreated path as their parent.
 				// For circular-fetch resolution we need the actual treated fetch-parent path,
 				// otherwise bidirectional checks compare against the wrong navigable path.
 				parentNavigablePath = fetchParentNavigablePath;
 			}
 			// The parent navigable path is {fk} if we are creating the domain result for the foreign key for a circular fetch
 			// In the following example, we create a circular fetch for the composite `Card.field.{id}.card.field`
 			// While creating the domain result for the foreign key of `Card#field`, we run into this condition
 			// We know that `Card#field` will be delayed because `EmbeddableForeignKeyResultImpl` enforces that
 			// so we can safely return null to avoid a stack overflow
 			/*
 				@Entity
 				public class Card {
 					@Id
 					private String id;
 					@ManyToOne
 					private CardField field;
 				}
 				@Entity
 				public class CardField {
 					@EmbeddedId
 					private PrimaryKey primaryKey;
 				}
 				@Embeddable
 				public class PrimaryKey {
 					@ManyToOne(optional = false)
 					private Card card;
 					@ManyToOne(optional = false)
 					private Key key;
 				}
 			 */
 			final String localName = parentNavigablePath.getLocalName();
 			if ( localName.equals( ForeignKeyDescriptor.PART_NAME )
 				|| localName.equals( ForeignKeyDescriptor.TARGET_PART_NAME ) ) {
 				// todo (6.0): maybe it's better to have a flag in creation state that marks if we are building a circular fetch domain result already to skip this?
 				return null;
 			}

+			final var sqlAstCreationState = creationState.getSqlAstCreationState();
+			if ( restrictions.hasSqlRestriction()
+					|| restrictions.isAffectedByFilters( sqlAstCreationState.getLoadQueryInfluencers() )
+					|| sqlAstCreationState.isProcedureOrNativeQuery() && restrictions.hasFilters() ) {
+				// An entity loaded through another path has not satisfied this association's predicate.
+				// Resolve its visibility before reusing the instance, retaining the physical key as usual.
+				return generateNonJoinedFetch( fetchParent, fetchablePath, fetchTiming,
+						sqlAstCreationState.getFromClauseAccess().getTableGroup( fetchParentNavigablePath ),
+						getSide( creationState ), creationState );
+			}
+
 			ModelPart parentModelPart = creationState.resolveModelPart( parentNavigablePath );
 			if ( parentModelPart instanceof EmbeddedIdentifierMappingImpl ) {
 				while ( parentNavigablePath instanceof EntityIdentifierNavigablePath ) {
 					parentNavigablePath = castNonNull( parentNavigablePath.getParent() );
 					assert parentNavigablePath != null;
 					parentModelPart = creationState.resolveModelPart( parentNavigablePath );
 				}
 			}
 			while ( parentModelPart instanceof EmbeddableValuedFetchable ) {
 				parentNavigablePath = castNonNull( parentNavigablePath.getParent() );
 				assert parentNavigablePath != null;
 				parentModelPart = creationState.resolveModelPart( parentNavigablePath );
 			}

 			if ( isBidirectionalAttributeName( parentNavigablePath, parentModelPart, fetchablePath, creationState ) ) {
 				return createCircularBiDirectionalFetch(
 						fetchablePath,
 						fetchParent,
 						parentNavigablePath,
 						fetchTiming,
 						creationState
 				);
 			}

 			/*
 						class Child {
 							@OneToOne
 							private Mother mother;
 						}

 						class Mother {
 							@OneToOne
 							private Child stepMother;
 						}

 				We have a circularity but it is not bidirectional
 			 */
 			return new CircularFetchImpl(
 					this,
 					fetchTiming,
 					fetchablePath,
 					fetchParent,
 					isSelectByUniqueKey( sideNature ),
 					parentNavigablePath,
 					determineCircularKeyResult( fetchParent, fetchablePath, creationState ),
 					creationState
 			);
 		}
 		return null;
 	}

 @Override
 	public EntityFetch generateFetch(
 			FetchParent fetchParent,
 			NavigablePath fetchablePath,
 			FetchTiming fetchTiming,
 			boolean selected,
 			String resultVariable,
 			DomainResultCreationState creationState) {

 		final var sqlAstCreationState = creationState.getSqlAstCreationState();
 		final var fromClauseAccess = sqlAstCreationState.getFromClauseAccess();

 		final var fetchParentNavigablePath = fetchParent.getNavigablePath();
 		final var parentTableGroup = fromClauseAccess.getTableGroup( fetchParentNavigablePath );

 		final var parentNavigablePath = castNonNull( fetchablePath.getParent() );
 		assert parentNavigablePath.equals( fetchParentNavigablePath )
 			|| fetchParentNavigablePath instanceof TreatedNavigablePath
 					&& parentNavigablePath.equals( fetchParentNavigablePath.getRealParent() );

 		/*
