+			assertThat( owner.getTarget() ).isNull();
+			owner.name = "cached target";
+		} );
+		assertStoredReference( scope, mapping, 2L, 2L );
+		if ( mapping.ownerType().getSimpleName().contains( "Filter" ) ) {
